#!/usr/bin/env python3
"""Is H_1 of the derived arc space of Spec C[x]/(x^N) cyclic over C[x][d], generated by the Euler syzygy
s_1 = x_0 e_1 - N x_1 e_0 (weight 2N+3)?  (S44.)  K = Koszul complex of f_n = d^n x_0^N; d acts on K_1 by the
derivation on coefficients and d(e_n) = e_(n+1) (since d f_n = f_(n+1)).  For each bidegree (D, r): dim H_1 versus the
dimension of span{monomials * d^k s_1} modulo boundaries.
Usage: python koszul_h1_cyclicity_20261018.py N Dmax
Session opus-2026-10-18-S44.
"""
import os, sys, json
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(HERE, '..', 'voa_singular_support'))
import flint
from vir_ss import block, block_index, deriv

P = 2147483647


def main():
    N, Dmax = int(sys.argv[1]), int(sys.argv[2])
    f = [{(2,) * N: 1}]
    while 2 * N + len(f) - 1 < Dmax:
        f.append({k: v % P for k, v in deriv(f[-1]).items()})
    nf = len(f)

    def k1_basis(D, r):
        return [(n, m) for n in range(nf) if D - 2 * N - n >= 0 and r - N >= 0 for m in block(D - 2 * N - n, r - N)]

    def rank(rows, n):
        if not rows or not n:
            return 0
        return flint.nmod_mat(len(rows), n, [x for rr in rows for x in rr], P).rank()

    # K_1 elements as dict {(n, mono): coeff}
    def d_K1(el):
        out = {}
        for (n, m), co in el.items():
            # derivation on the coefficient monomial
            for mm, c2 in deriv({m: 1}).items():
                out[(n, mm)] = (out.get((n, mm), 0) + co * c2) % P
            if n + 1 < nf:
                out[(n + 1, m)] = (out.get((n + 1, m), 0) + co) % P
        return {k: v for k, v in out.items() if v}

    def x_K1(el, j):
        k = j + 2
        return {(n, tuple(sorted(m + (k,), reverse=True))): co for (n, m), co in el.items()}

    s1 = {(1, (2,)): 1, (0, (3,)): (-N) % P}   # x_0 e_1 - N x_1 e_0 ; x_0 <-> part 2, x_1 <-> part 3
    gen = {(2 * N + 3, N + 1): [s1]}
    ok = True
    rows_out = []
    for D in range(2 * N + 3, Dmax + 1):
        for r in range(N + 1, D // 2 + 1):
            B1 = k1_basis(D, r)
            if not B1:
                continue
            i1 = {b: i for i, b in enumerate(B1)}
            idx = block_index(D, r)
            # d1 rows
            rows1 = []
            for (n, m) in B1:
                row = [0] * len(idx)
                for mono, co in f[n].items():
                    lam = tuple(sorted(mono + m, reverse=True))
                    row[idx[lam]] = (row[idx[lam]] + co) % P
                rows1.append(row)
            rk1 = rank(rows1, len(idx))
            dimZ = len(B1) - rk1
            # boundaries
            brows = []
            for n1 in range(nf):
                for n2 in range(n1 + 1, nf):
                    w = D - 4 * N - n1 - n2
                    if w < 0 or r - 2 * N < 0:
                        continue
                    for m in block(w, r - 2 * N):
                        row = [0] * len(B1)
                        for mono, co in f[n1].items():
                            j = i1[(n2, tuple(sorted(mono + m, reverse=True)))]
                            row[j] = (row[j] + co) % P
                        for mono, co in f[n2].items():
                            j = i1[(n1, tuple(sorted(mono + m, reverse=True)))]
                            row[j] = (row[j] - co) % P
                        brows.append(row)
            rkB = rank(brows, len(B1))
            h1 = dimZ - rkB
            # span of generated elements
            els = list(gen.get((D, r), []))
            for j in range(0, D):
                for e in gen.get((D - j - 2, r - 1), []):
                    els.append(x_K1(e, j))
            for e in gen.get((D - 1, r), []):
                de = d_K1(e)
                if de:
                    els.append(de)
            gen[(D, r)] = els
            erows = []
            for e in els:
                row = [0] * len(B1)
                for key, co in e.items():
                    row[i1[key]] = (row[i1[key]] + co) % P
                erows.append(row)
            span = rank(brows + erows, len(B1)) - rkB if erows else 0
            if h1 or span:
                rows_out.append(dict(D=D, r=r, H1=h1, span=span))
                if span != h1:
                    ok = False
            # prune generator list to a spanning subset (row-reduce)
            if erows:
                M = flint.nmod_mat(len(erows), len(B1), [x for rr in erows for x in rr], P)
                R, rk = M.rref()
                keep = []
                for rr in R.tolist()[:rk]:
                    keep.append({B1[c]: int(x) for c, x in enumerate(rr) if int(x)})
                gen[(D, r)] = keep
    tot_h1 = sum(x['H1'] for x in rows_out)
    tot_sp = sum(x['span'] for x in rows_out)
    print('N=%d, D<=%d: H_1 cyclic over C[x][d] (generated by the Euler syzygy) at every bidegree: %s; total dim H_1 = %d, span = %d'
          % (N, Dmax, ok, tot_h1, tot_sp))
    bad = [(x['D'], x['r'], x['H1'], x['span']) for x in rows_out if x['H1'] != x['span']]
    print('  first deviations (D, r, dim H_1, span):', bad[:10])
    json.dump(dict(N=N, Dmax=Dmax, ok=ok, rows=rows_out), open(os.path.join(HERE, 'koszul_h1_cyclicity_N%d_D%d.json' % (N, Dmax)), 'w'), indent=1)


if __name__ == '__main__':
    main()
